    const PLUGIN_CODE_KEY: &'static str = "plugin_code";
    const PLUGIN_3D_KEY: &'static str = "plugin_3d";
    const PLUGIN_VIDEO_KEY: &'static str = "plugin_video";
    const YT_DIR_KEY: &'static str = "yt_download_dir";
    const DOSBOX_PATH_KEY: &'static str = "dosbox_path";
    const DOSBOX_KEEP_OPEN_KEY: &'static str = "dosbox_keep_open";
    const DOSBOX_MACHINE_KEY: &'static str = "dosbox_machine";
    const DOSBOX_SVGA_KEY: &'static str = "dosbox_svga";
    const YT_QUALITY_KEY: &'static str = "yt_max_height";
    const YT_OPEN_FOLDER_KEY: &'static str = "yt_open_folder_after";
    const YT_COOKIES_KEY: &'static str = "yt_cookies_browser";
    const RECOLOR_PLAYBACK_KEY: &'static str = "recolor_playback";
    const SHOW_FPS_KEY: &'static str = "show_fps";
    const STEAM_KEY_KEY: &'static str = "steam_api_key";
    const MA_KEY_KEY: &'static str = "modarchive_api_key";
    const RAIL_SECTION_KEY: &'static str = "rail_section";
    const RECENTS_KEY: &'static str = "recent_dirs";
    const RAIL_EXPANDED_KEY: &'static str = "rail_expanded";
    const PANEL_LAYOUTS_KEY: &'static str = "panel_layouts";
    const PLUGIN_GIFS_KEY: &'static str = "plugin_gifs";
    const PLUGIN_WEB_KEY: &'static str = "plugin_web";
    const PLUGIN_ICONS_KEY: &'static str = "plugin_icons";
    const PLUGIN_VECTORS_KEY: &'static str = "plugin_vectors";
    const PLUGIN_LOSPEC_KEY: &'static str = "plugin_lospec";
    const PLUGIN_PH_KEY: &'static str = "plugin_polyhaven";
    const PLUGIN_GFONTS_KEY: &'static str = "plugin_gfonts";
    const PLUGIN_MA_KEY: &'static str = "plugin_modarchive";
    const PLUGIN_16C_KEY: &'static str = "plugin_16colo";
    const PLUGIN_YOUTUBE_KEY: &'static str = "plugin_youtube";
    const PLUGIN_STEAM_KEY: &'static str = "plugin_steam";
    const PLUGIN_IMAGES_KEY: &'static str = "plugin_images";
    const PLUGIN_AUDIOSEARCH_KEY: &'static str = "plugin_audiosearch";
    const PLUGIN_DA_KEY: &'static str = "plugin_deviantart";
    const GIF_RECOLOR_KEY: &'static str = "gif_recolor";
    const GIF_SPEED_KEY: &'static str = "gif_speed";
