        eframe::set_value(storage, Self::UI_FONT_SCALE_KEY, &self.ui_font_scale);
        eframe::set_value(storage, Self::THUMB_KEY, &self.thumb_size);
        eframe::set_value(storage, Self::FAV_KEY, &self.favorites);
        let fav_colors: Vec<(PathBuf, [u8; 3])> = self
            .fav_colors
            .iter()
            .map(|(p, &c)| (p.clone(), c))
            .collect();
        eframe::set_value(storage, Self::FAV_COLORS_KEY, &fav_colors);
        let fav_names: Vec<(PathBuf, String)> = self
            .fav_names
            .iter()
            .map(|(p, n)| (p.clone(), n.clone()))
            .collect();
        eframe::set_value(storage, Self::FAV_NAMES_KEY, &fav_names);
        eframe::set_value(
            storage,
            Self::FAV_BAR_COLORED_KEY,
            &self.fav_bar_colored_only,
        );
        let filters: Vec<Vec<String>> = self
            .saved_filters
            .iter()
            .map(|(name, spec)| {
                let mut row = vec![name.clone()];
                row.extend(spec.record());
                row
            })
            .collect();
        eframe::set_value(storage, Self::SAVED_FILTERS_KEY, &filters);
        let openers: Vec<Vec<String>> = self.openers.iter().map(|o| o.record()).collect();
        eframe::set_value(storage, Self::OPENERS_KEY, &openers);
        let folder_actions: Vec<Vec<String>> =
            self.folder_actions.iter().map(|o| o.record()).collect();
        eframe::set_value(storage, Self::FOLDER_ACTIONS_KEY, &folder_actions);
        eframe::set_value(storage, Self::PLUGIN_PDF_KEY, &self.plugin_pdf);
        eframe::set_value(storage, Self::PLUGIN_AUDIO_KEY, &self.plugin_audio);
        eframe::set_value(storage, Self::PLUGIN_CODE_KEY, &self.plugin_code);
        eframe::set_value(storage, Self::PLUGIN_3D_KEY, &self.plugin_3d);
        eframe::set_value(storage, Self::PLUGIN_VIDEO_KEY, &self.plugin_video);
        eframe::set_value(storage, Self::YT_DIR_KEY, &self.yt_download_dir);
        eframe::set_value(storage, Self::DOSBOX_PATH_KEY, &self.dosbox_path);
        eframe::set_value(storage, Self::DOSBOX_KEEP_OPEN_KEY, &self.dosbox_keep_open);
        eframe::set_value(storage, Self::DOSBOX_MACHINE_KEY, &self.dosbox_machine);
        eframe::set_value(storage, Self::DOSBOX_SVGA_KEY, &self.dosbox_svga);
        eframe::set_value(storage, Self::YT_QUALITY_KEY, &self.yt_max_height);
        eframe::set_value(
            storage,
            Self::YT_OPEN_FOLDER_KEY,
            &self.yt_open_folder_after,
        );
        eframe::set_value(storage, Self::YT_COOKIES_KEY, &self.yt_cookies_browser);
        eframe::set_value(storage, Self::RECOLOR_PLAYBACK_KEY, &self.recolor_playback);
        eframe::set_value(storage, Self::SHOW_FPS_KEY, &self.show_fps);
        // Deliberately NOT written to the shared storage blob any more — keys go to secrets.json,
        // which the user can exclude from dotfile sync. Old blobs keep their copy until overwritten;
        // that's the migration read above, and clearing a key in Preferences removes the file.
        if let Err(e) = crate::secrets::save(
            &self.secrets_file,
            &[
                ("steam_api_key", &self.steam_api_key, "Steam Web API key — steamcommunity.com/dev/apikey"),
                ("ma_key", &self.ma_key, "ModArchive API key (optional; browsing works without one)"),
                ("da_client_id", &self.da_client_id, "DeviantArt app client_id — deviantart.com/developers"),
                ("da_client_secret", &self.da_client_secret, "DeviantArt app client_secret (keep private)"),
            ],
        ) {
            eprintln!("secrets.json: {e}");
        }
        eframe::set_value(storage, Self::PLUGIN_GIFS_KEY, &self.plugin_gifs);
        eframe::set_value(storage, Self::PLUGIN_WEB_KEY, &self.plugin_web);
        eframe::set_value(storage, Self::PLUGIN_ICONS_KEY, &self.plugin_icons);
        eframe::set_value(storage, Self::PLUGIN_VECTORS_KEY, &self.plugin_vectors);
        eframe::set_value(storage, Self::PLUGIN_LOSPEC_KEY, &self.plugin_lospec);
