    #[test]
    fn crop_locked_aspect_holds_and_matches_pixels() {
        // update_crop keeps the normalized w/h at a_norm when a corner is dragged.
        let out = update_crop([0.1, 0.1, 0.4, 0.4], 2, 0.3, 0.0, Some(1.5));
        assert!((out[2] / out[3] - 1.5).abs() < 0.05, "w/h {}", out[2] / out[3]);
        // crop_apply_ratio yields a box whose PIXEL ratio matches (square image → px_aspect 1).
        let c = crop_apply_ratio([0.1, 0.1, 0.8, 0.8], 16, 9, 1.0);
        let pixel_ratio = (c[2] / c[3]) * 1.0;
        assert!((pixel_ratio - 16.0 / 9.0).abs() < 0.02, "pixel ratio {pixel_ratio}");
        // Flipping to 9:16 gives the reciprocal.
        let c2 = crop_apply_ratio(c, 9, 16, 1.0);
        let pr2 = (c2[2] / c2[3]) * 1.0;
        assert!((pr2 - 9.0 / 16.0).abs() < 0.02, "flipped ratio {pr2}");
    }

    #[test]
    fn batch_builds_grid_from_preset_and_maps_formats() {
        // The headless batch path: a default ANSI-Shade preset (snap 9×16) on an 18×32
        // opaque image yields a 2×2 cell grid — proving `build_ansi_grid_from_preset`
        // (the twin of the GUI `build_ansi_grid`) runs end-to-end without an App.
        let mut p = FxPreset::default();
        p.dither_method = crate::thumb::DITHER_ANSI;
        p.shade_snap916 = true;
        p.shade_vga50 = false;
        p.shade_fit_chars = false;
        p.resize_on = false;
        let palette = vec![[0, 0, 0, 255], [128, 128, 128, 255], [255, 255, 255, 255]];
        let (w, h) = (18usize, 32usize);
        let rgba = vec![200u8; w * h * 4];
        let (grid, _work, tw, th, font8) = build_ansi_grid_from_preset(&p, &palette, w, h, &rgba);
        assert_eq!((grid.cols, grid.rows), (2, 2), "9×16 cells over 18×32");
        assert_eq!((tw, th), (18, 32));
        assert!(!font8);
        // The serializer produces a non-empty file with a 128-byte SAUCE trailer.
        let (bytes, ext, _note) = serialize_textmode(&grid, 1, true, false, "t", "20260817");
        assert_eq!(ext, "ans");
        assert!(bytes.len() > 128 && &bytes[bytes.len() - 128..][..5] == b"SAUCE");
        // --format name → export-code mapping.
        assert_eq!(textmode_format_code("auto"), Some(0));
        assert_eq!(textmode_format_code("xb"), Some(4));
        assert_eq!(textmode_format_code("tnd"), Some(5));
        assert_eq!(textmode_format_code("nope"), None);
    }

    #[test]
    fn builtin_fx_presets_parse_and_reference_bundled_palettes() {
        let fx = builtin_fx_presets();
        assert!(
            fx.len() >= 20,
            "bundled PixelFX presets embedded ({} found)",
            fx.len()
        );
        assert!(
            fx.iter().any(|p| p.name == "Gameboy"),
            "a known preset is present"
        );
        // Every referenced palette must resolve to embedded contents — else a fresh install would
        // recall a preset whose palette silently doesn't exist.
        for p in fx {
            if let Some(pal) = &p.selected_palette {
                let text = builtin_palette_contents(pal).unwrap_or_else(|| {
                    panic!("preset {:?} references missing palette {:?}", p.name, pal)
                });
                assert!(
                    !crate::thumb::parse_gpl(text).is_empty(),
                    "{:?} palette parsed empty",
                    p.name
                );
            }
        }
        // Every bundled preset is filed under the Factory folder.
        assert!(
            fx.iter()
                .all(|p| p.folder.as_deref() == Some(FX_FACTORY_FOLDER)),
            "bundled presets are in the Factory folder"
        );
        // Merge is idempotent: overlaying builtins onto a list that already has them adds nothing.
        let mut have: Vec<FxPreset> = fx.to_vec();
        let before = have.len();
        merge_builtin_fx_presets(&mut have);
        assert_eq!(
            have.len(),
            before,
            "merging builtins twice must not duplicate"
        );

        // Migration: a folder-less copy of a builtin (the earlier release) is moved into Factory;
        // a builtin the user re-filed elsewhere is left; a user-only preset is untouched.
        let mut user = vec![
            FxPreset {
                name: "Gameboy".into(),
                folder: None,
                ..Default::default()
            },
            FxPreset {
                name: "CGA1".into(),
                folder: Some("Mine".into()),
                ..Default::default()
            },
            FxPreset {
                name: "My Look".into(),
                folder: None,
                ..Default::default()
            },
        ];
        merge_builtin_fx_presets(&mut user);
        let f = |n: &str| user.iter().find(|p| p.name == n).unwrap().folder.clone();
        assert_eq!(
            f("Gameboy").as_deref(),
            Some(FX_FACTORY_FOLDER),
            "folderless builtin → Factory"
        );
        assert_eq!(f("CGA1").as_deref(), Some("Mine"), "re-filed builtin kept");
        assert_eq!(f("My Look"), None, "user preset untouched");
        assert!(user.len() > 3, "missing builtins were appended");

        // Read-only gate keys on the name, not the folder.
        assert!(is_builtin_fx_name("Gameboy"), "bundled preset is read-only");
        assert!(!is_builtin_fx_name("My Look"), "user preset is editable");
    }

    #[test]
    fn auto_export_embeds_custom_background_as_xbin() {
        // A grid whose background is a custom Ink/Paper colour (not an EGA colour) must NOT export
        // as a plain/truecolor .ans (editors drop the bg to black) — Auto picks XBin, which embeds
        // the palette so the custom background survives.
        use crate::thumb::{AnsiCell, AnsiGrid};
        let magenta = [200u8, 20, 180, 255];
        let grid = AnsiGrid {
            cols: 2,
            rows: 1,
            cell_w: 8,
            cell_h: 16,
            palette: vec![[220, 220, 220, 255], magenta], // ink 0, paper 1
            cells: vec![
                AnsiCell { fg: 0, bg: 1, ch: b'A' },
                AnsiCell { fg: 0, bg: 1, ch: b'B' },
            ],
        };
        let (bytes, ext, _) = serialize_textmode(&grid, 0 /* Auto */, false, false, "t", "20260101");
        assert_eq!(ext, "xb", "custom-bg grid auto-exports as XBin");
        assert_eq!(&bytes[..5], b"XBIN\x1a", "XBin header");
        // The embedded palette (6-bit DAC, after the 11-byte header) contains the magenta paper.
        let pal = &bytes[11..11 + 48];
        let has_magenta = pal.chunks_exact(3).any(|c| {
            let (r, g, b) = ((c[0] as u32) << 2, (c[1] as u32) << 2, (c[2] as u32) << 2);
            r.abs_diff(200) < 12 && g.abs_diff(20) < 12 && b.abs_diff(180) < 12
        });
        assert!(has_magenta, "the custom paper colour is embedded in the XBin palette");
    }

    #[test]
    fn coerce_palette_16_fills_all_slots() {
        // ≥16 → first 16; fewer → cycle to fill; empty → black.
        let many: Vec<[u8; 4]> = (0..20).map(|i| [i as u8, 0, 0, 255]).collect();
        assert_eq!(coerce_palette_16(&many)[15], [15, 0, 0, 255]);
        let four = [[10, 0, 0, 255], [20, 0, 0, 255], [30, 0, 0, 255], [40, 0, 0, 255]];
        let c = coerce_palette_16(&four);
        assert_eq!(c[0], four[0]);
        assert_eq!(c[4], four[0], "cycles after 4");
        assert_eq!(c[15], four[3], "every slot filled, none black");
        assert_eq!(coerce_palette_16(&[]), [[0, 0, 0, 255]; 16]);
    }

